set -u; R=/scratch/jjyeung/orch_n30; mkdir -p $R/sb_queue
mkdir -p $R/sb_rowA/prompts $R/sb_rowA/out
base64 -d > $R/sb_rowA/prompts/sb_rowA.md <<'B64'

B64
mkdir -p $R/sb_rowB/prompts $R/sb_rowB/out
base64 -d > $R/sb_rowB/prompts/sb_rowB.md <<'B64'

B64
mkdir -p $R/sb_rowC/prompts $R/sb_rowC/out
base64 -d > $R/sb_rowC/prompts/sb_rowC.md <<'B64'

B64
mkdir -p $R/sb_rowD/prompts $R/sb_rowD/out
base64 -d > $R/sb_rowD/prompts/sb_rowD.md <<'B64'

B64
cat > $R/sb_queue/codexq.sh <<'EOQ'
#!/bin/bash
# Launch queued Codex builds when fewer than 6 swarm_build Codex builds run and >100 GB RAM is available.
R=/scratch/jjyeung/orch_n30; B=/data2/jjyeung/agent_project_data/distillation_orchestrator_20260918/orch_n30; Q=$R/sb_queue/queue.txt
while true; do
  t=$(head -1 $Q 2>/dev/null); [ -z "$t" ] && { sleep 60; continue; }
  n=$(pgrep -f "codex_dispatch.sh implement $R/sb_" | wc -l); a=$(free -g | awk '/Mem:/{print $7}')
  if [ "$n" -lt 6 ] && [ "$a" -gt 100 ]; then
    sed -i 1d $Q
    tmux new-session -d -s $t "bash $B/tools/codex_local.sh implement $R/$t $R/$t/prompts/$t.md --model gpt-6-astra --effort high --label $t --skip-git-check > $R/$t/dispatch.log 2>&1"
    echo "$(date -u +%FT%TZ) launched $t (running before: $n, avail $a)" >> $R/sb_queue/codexq.log; sleep 20
  else sleep 60; fi
done
EOQ
chmod +x $R/sb_queue/codexq.sh
printf 'sb_rowA\nsb_rowB\nsb_rowC\nsb_rowD\n' >> $R/sb_queue/queue.txt
tmux has-session -t sb_codexq 2>/dev/null || tmux new-session -d -s sb_codexq "bash $R/sb_queue/codexq.sh"
sleep 90; cat $R/sb_queue/codexq.log; cat $R/sb_queue/queue.txt; pgrep -af "codex_dispatch.sh implement" | cut -c1-140
